// Reports the ten most frequent words in a file.
// A word is a maximal run of ASCII letters and digits; everything else separates.

const decoder = new TextDecoder("latin1");

function isWordByte(b: number): boolean {
  return (b >= 0x30 && b <= 0x39) || (b >= 0x41 && b <= 0x5a) ||
    (b >= 0x61 && b <= 0x7a);
}

/** Incrementally counts words across arbitrary chunk boundaries. */
export class WordCounter {
  readonly counts = new Map<string, number>();
  private pending = "";

  push(chunk: Uint8Array): void {
    let start = -1;
    for (let i = 0; i < chunk.length; i++) {
      if (isWordByte(chunk[i])) {
        if (start < 0) start = i;
      } else if (start >= 0 || this.pending) {
        const part = start >= 0 ? decoder.decode(chunk.subarray(start, i)) : "";
        this.add(this.pending + part);
        this.pending = "";
        start = -1;
      }
    }
    if (start >= 0) {
      this.pending += decoder.decode(chunk.subarray(start));
    }
  }

  finish(): Map<string, number> {
    if (this.pending) {
      this.add(this.pending);
      this.pending = "";
    }
    return this.counts;
  }

  private add(word: string): void {
    const w = word.toLowerCase();
    this.counts.set(w, (this.counts.get(w) ?? 0) + 1);
  }
}

/** Words are pure ASCII, so UTF-16 code unit order equals byte order. */
export function topWords(
  counts: Map<string, number>,
  n = 10,
): [string, number][] {
  return [...counts].sort((a, b) =>
    b[1] - a[1] || (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0)
  ).slice(0, n);
}

export function format(top: [string, number][]): string {
  return top.map(([w, c]) => `${w} ${c}\n`).join("");
}

export function report(bytes: Uint8Array): string {
  const counter = new WordCounter();
  counter.push(bytes);
  return format(topWords(counter.finish()));
}

async function main(): Promise<void> {
  const path = Deno.args[0];
  if (path === undefined) {
    console.error("usage: main.ts <file>");
    Deno.exit(2);
  }
  const counter = new WordCounter();
  using file = await Deno.open(path, { read: true });
  for await (const chunk of file.readable) counter.push(chunk);
  const out = format(topWords(counter.finish()));
  if (out) await Deno.stdout.write(new TextEncoder().encode(out));
}

if (import.meta.main) {
  await main();
}
EOF
cat > main_test.ts <<'EOF'
import { report, WordCounter, format, topWords } from "./main.ts";

const enc = (s: string) => new TextEncoder().encode(s);

function assertEquals(a: unknown, b: unknown) {
  if (JSON.stringify(a) !== JSON.stringify(b)) {
    throw new Error(`expected ${JSON.stringify(b)}, got ${JSON.stringify(a)}`);
  }
}

Deno.test("empty input writes nothing", () => {
  assertEquals(report(enc("")), "");
  assertEquals(report(enc("  ,.!? \n\t é ü")), "");
});

Deno.test("case-insensitive, lower-cased", () => {
  assertEquals(report(enc("Hello HELLO hello")), "hello 3\n");
});

Deno.test("non-ASCII and punctuation separate words", () => {
  assertEquals(report(enc("café don't a_b")), "a 1\nb 1\ncaf 1\ndon 1\nt 1\n");
});

Deno.test("digits are word characters", () => {
  assertEquals(report(enc("abc123 ABC123 9")), "abc123 2\n9 1\n");
});

Deno.test("ties broken by byte order, top ten only", () => {
  const words = "l k j i h g f e d c b a 0 Z";
  assertEquals(
    report(enc(words + " b")),
    "b 2\n0 1\na 1\nc 1\nd 1\ne 1\nf 1\ng 1\nh 1\ni 1\n",
  );
});

Deno.test("words spanning chunk boundaries", () => {
  const text = enc("foo bar foobar Foo  baz");
  for (let size = 1; size <= text.length; size++) {
    const c = new WordCounter();
    for (let i = 0; i < text.length; i += size) c.push(text.subarray(i, i + size));
    assertEquals(
      format(topWords(c.finish())),
      "foo 2\nbar 1\nbaz 1\nfoobar 1\n",
    );
  }
});

Deno.test("invalid UTF-8 bytes separate words", () => {
  assertEquals(report(new Uint8Array([0x61, 0xff, 0x62, 0x80, 0x61])), "a 2\nb 1\n");
});
EOF
deno check main.ts main_test.ts && deno test -q 2>&1 | tail -5
printf 'The the THE cat; Cat. dog\xff\xfedog zebra' > /tmp/wf.txt && deno run --allow-read main.ts /tmp/wf.txt; echo "exit $?"
deno run --allow-read main.ts /dev/null; echo "exit $?"

